{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana rent stabilization annual increase cap formula","requirement":"A landlord may raise rent each year by no more than 3% of the current rent or 80% of the Consumer Price Index change, whichever is less.","key_value":"3% or 80% of CPI, whichever is less","coverage_conditions":null,"applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Santa Ana Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"Your landlord can only raise your rent by a certain amount each year. The increase cannot be more than 3% of your current rent or 80% of the Consumer Price Index (CPI) change, whichever is less.","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Maximum allowable rent increase for September 1, 2026 through August 31, 2027","requirement":"For the period September 1, 2026 through August 31, 2027, a landlord may not raise rent by more than 2.87 percent.","key_value":"2.87% (September 1, 2026 – August 31, 2027)","coverage_conditions":null,"applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":"2026-09-01","citation":"Santa Ana Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"2.87 percent is the maximum allowable rent increase for the period of September 1, 2026 through August 31, 2027.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Registration fee pass-through cap and overcharge reimbursement","requirement":"A landlord charging a registration fee pass-through greater than $50 must reimburse the tenant for the overpayment; the pass-through is charged by rental unit, not by the number of tenants, and cannot be charged for prior monthly installments.","key_value":"$50 per rental unit","coverage_conditions":"Pass-through fee charged by rental unit rather than by number of tenants; the Ordinance allows but does not require landlords to charge it.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Santa Ana Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"If a landlord charges a tenant a pass-through fee greater than $50, the landlord shall reimburse the tenant for the registration fee pass-through overpayment.","interaction":null,"confidence":0.6,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Just cause eviction requirement","requirement":"A landlord must have a valid reason to evict a tenant, such as nonpayment of rent, breaking the lease, or the landlord moving into the property; for certain reasons the landlord may have to help pay the tenant's moving costs.","key_value":null,"coverage_conditions":null,"applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Santa Ana Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"Just cause evictions: Your landlord must have a valid reason to evict you. This could be for not paying rent, breaking the lease, or if the landlord wants to move into the property themselves.","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
